CREATE TABLE public.rm_cards (id TEXT NOT NULL DEFAULT gen_random_uuid()::text PRIMARY KEY, vehicle_id TEXT NOT NULL, inspector_name TEXT, inspector_phone TEXT, inspector_type TEXT NOT NULL DEFAULT 'admin', token TEXT, token_expires_at TIMESTAMPTZ, mileage_at_inspection NUMERIC, items_checked JSONB NOT NULL DEFAULT '[]'::jsonb, overall_notes TEXT, status TEXT NOT NULL DEFAULT 'submitted', created_by_admin TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), submitted_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.rm_cards TO authenticated; GRANT ALL ON public.rm_cards TO service_role; ALTER TABLE public.rm_cards ENABLE ROW LEVEL SECURITY; CREATE POLICY "rm view" ON public.rm_cards FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.has_role(auth.uid(), 'runner'::app_role)); CREATE POLICY "rm insert" ON public.rm_cards FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'::app_role) OR public.has_role(auth.uid(), 'runner'::app_role)); CREATE POLICY "rm update" ON public.rm_cards FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.has_role(auth.uid(), 'runner'::app_role)); CREATE POLICY "rm delete" ON public.rm_cards FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'::app_role) OR public.has_role(auth.uid(), 'runner'::app_role)); CREATE INDEX idx_rm_cards_vehicle ON public.rm_cards (vehicle_id); CREATE INDEX idx_rm_cards_token ON public.rm_cards (token); CREATE TRIGGER rm_cards_touch_updated_at BEFORE UPDATE ON public.rm_cards FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); ALTER TABLE public.vehicles ADD COLUMN IF NOT EXISTS rm_history JSONB NOT NULL DEFAULT '[]'::jsonb; ALTER TABLE public.vehicles ADD COLUMN IF NOT EXISTS last_rm_date TIMESTAMPTZ; ALTER TABLE public.vehicles ADD COLUMN IF NOT EXISTS last_rm_mileage NUMERIC;